        this.jointRA10.xRot = 0.0f;
        this.jointLA1.xRot = 0.0f;
        this.jointLA2.xRot = 0.0f;
        this.jointLA2.yRot = 0.0f;
        this.jointLA2.zRot = 0.0f;
        this.jointLA4.xRot = 0.0f;
        this.jointLA6.xRot = 0.0f;
        this.jointLA8.xRot = 0.0f;
        this.jointLA10.xRot = 0.0f;
        this.mainbody.y = 0.0f;
        this.mainbody.x = 0.0f;
